// ═══════════════════════════════════════════════════════════
// NovelBlocks — Game settings: name, version and icon of the
// game, saved in options.rpy (the icons are generated by main.js)
// ═══════════════════════════════════════════════════════════

let gameInfo = null;
let gameIconPending = '';     // image picked but not saved yet
let buildNameTouched = false; // once edited by hand it no longer follows the name

async function openGameSettings() {
  if (!gamePath) { notify(t('open_project_first'), 'err'); return; }
  gameInfo = await window.api.getGameInfo();
  if (!gameInfo) return;
  await loadPatchInfo();
  initPatchDraft();
  gameIconPending = '';
  // A build name that already matches the game's name keeps following it
  buildNameTouched = gameInfo.buildName !== suggestBuildName(gameInfo.name);
  renderGameSettings();
  setGameTab('general');
  document.getElementById('game-overlay').classList.add('open');
  document.getElementById('game-name').focus();
}

// General (name, version, icon) and Patch
function setGameTab(tab) {
  for (const id of ['general', 'patch']) {
    const on = id === tab;
    document.getElementById('game-tab-' + id).setAttribute('aria-selected', String(on));
    document.getElementById('game-panel-' + id).hidden = !on;
  }
  document.querySelector('#game-overlay .app-box').classList.toggle('wide', tab === 'patch');
}

function closeGameSettings() {
  document.getElementById('game-overlay').classList.remove('open');
}

// build.name has to be plain ASCII without spaces: it names the files of the builds
function suggestBuildName(name) {
  return (name || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]+/g, '');
}

function isValidBuildName(s) {
  return /^[A-Za-z0-9_.-]+$/.test(s);
}

function gameIconSrc() {
  if (gameIconPending) return 'file:///' + gameIconPending.replace(/\\/g, '/').split('/').map(encodeURIComponent).join('/').replace(/^([A-Za-z])%3A/, '$1:');
  if (gameInfo.iconExists) return getGameFileURL(gameInfo.icon) + '?' + Date.now();
  return '';
}

function gameIconPreviewHtml() {
  const src = gameIconSrc();
  return src ? `<img src="${src}" alt="">` : icon('image', 32);
}

function gameIconFilesHtml() {
  const row = (ok, label, file) => `<li class="${ok ? 'ok' : ''}"><span>${label}</span><code>${escHtml(file)}</code>
    <span class="game-file-state">${t(ok ? 'game_icon_ready' : 'game_icon_missing')}</span></li>`;
  const pending = !!gameIconPending;
  return `<ul class="game-icon-files">
    ${row(pending || gameInfo.iconExists, t('game_icon_window'), gameInfo.icon)}
    ${row(pending || gameInfo.hasIco, 'Windows', 'icon.ico')}
    ${row(pending || gameInfo.hasIcns, 'Mac', 'icon.icns')}
  </ul>`;
}

function renderGameSettings() {
  document.getElementById('game-body').innerHTML = `
    <div id="game-panel-general" role="tabpanel" aria-labelledby="game-tab-general">
    <div class="game-icon-row">
      <div class="game-icon-preview" id="game-icon-preview">${gameIconPreviewHtml()}</div>
      <div class="game-icon-info">
        <div class="form-label">${t('game_icon')}</div>
        <p class="settings-hint">${t('game_icon_hint')}</p>
        <button class="btn btn-secondary btn-sm" onclick="pickGameIcon()">${icon('image', 14)}${t('game_icon_change')}</button>
        <div id="game-icon-files">${gameIconFilesHtml()}</div>
      </div>
    </div>
    <div class="form-group">
      <label class="form-label" for="game-name">${t('game_name')}</label>
      <input class="form-input" id="game-name" value="${escHtml(gameInfo.name)}" oninput="onGameNameInput()" onkeydown="onGameSettingsKey(event)">
    </div>
    <div class="form-row">
      <div class="form-group">
        <label class="form-label" for="game-version">${t('game_version')}</label>
        <input class="form-input" id="game-version" value="${escHtml(gameInfo.version)}" placeholder="1.0" oninput="refreshPatchZipName()" onkeydown="onGameSettingsKey(event)">
        <p class="settings-hint">${t('game_version_hint')}</p>
      </div>
      <div class="form-group">
        <label class="form-label" for="game-build">${t('game_build_name')}</label>
        <input class="form-input game-mono" id="game-build" value="${escHtml(gameInfo.buildName)}" spellcheck="false"
          oninput="buildNameTouched = true; validateGameSettings(); refreshPatchZipName()" onkeydown="onGameSettingsKey(event)" aria-describedby="game-build-hint">
        <p class="settings-hint" id="game-build-hint">${t('game_build_hint')}</p>
      </div>
    </div>
    <p class="game-note">${t('game_saves_note')}</p>
    </div>
    <div id="game-panel-patch" class="patch-panel" role="tabpanel" aria-labelledby="game-tab-patch" hidden></div>`;
  renderPatchSettings();
  validateGameSettings();
}

function onGameNameInput() {
  if (!buildNameTouched) {
    document.getElementById('game-build').value = suggestBuildName(document.getElementById('game-name').value);
  }
  validateGameSettings();
  refreshPatchZipName();
}

function validateGameSettings() {
  const name = document.getElementById('game-name');
  const build = document.getElementById('game-build');
  const nameOk = name.value.trim() !== '';
  const buildOk = isValidBuildName(build.value.trim());
  name.classList.toggle('invalid', !nameOk);
  build.classList.toggle('invalid', !buildOk);
  build.setAttribute('aria-invalid', String(!buildOk));
  document.getElementById('game-build-hint').classList.toggle('error', !buildOk);
  document.getElementById('game-save-btn').disabled = !nameOk || !buildOk;
}

function onGameSettingsKey(e) {
  if (e.key === 'Enter' && !document.getElementById('game-save-btn').disabled) { e.preventDefault(); saveGameSettings(); }
}

async function pickGameIcon() {
  const file = await window.api.selectGameIcon();
  if (!file) return;
  gameIconPending = file;
  document.getElementById('game-icon-preview').innerHTML = gameIconPreviewHtml();
  document.getElementById('game-icon-files').innerHTML = gameIconFilesHtml();
}

async function saveGameSettings() {
  const info = {
    name: document.getElementById('game-name').value.trim(),
    version: document.getElementById('game-version').value.trim(),
    buildName: document.getElementById('game-build').value.trim()
  };
  if (!info.name || !isValidBuildName(info.buildName)) return;
  if (!await window.api.saveGameInfo(info)) { notify(t('save_error', 'options.rpy'), 'err'); return; }
  let message = t('game_saved');
  if (gameIconPending) {
    const r = await window.api.setGameIcon(gameIconPending);
    if (!r.ok) { notify(t('game_icon_error'), 'err'); return; }
    if (r.small) message = t('game_icon_small');
  }
  if (!await savePatchSettings()) return;
  closeGameSettings();
  notify(message, 'ok');
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && document.getElementById('game-overlay').classList.contains('open')
    && !document.querySelector('.app-dialog-overlay')) closeGameSettings();
});
